-- Blade's Edge Mountains: creature abilities
-- Most of the zone's creatures (the Bladespire and Bloodmaul ogres, the Black Dragonflight, the Gronn, the arakkoa and wildlife)
-- had no AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows
-- needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The
-- creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '16952,17855,18690,18692,18693,19747,19943,19944,19945,19948,19956,19960,19961,19963,19973,19980,19982,19983,19984,19985,19986,19987,19988,19989,19990,19991,19993,20161,20211,20214,20329,20600,20601,20609,20614,20714,20723,20726,20728,20729,20730,20731,20732,20747,20748,20751,20753,20757,20924,20925,20987,20998,21004,21021,21023,21032,21033,21040,21042,21046,21047,21048,21057,21123,21124,21189,21254,21300,21319,21325,21326,21373,21381,21382,21383,21389,21423,21492,21497,21516,21519,21637,21810,21837,21839,21956,22044,22052,22099,22123,22132,22160,22174,22181,22182,22196,22204,22217,22221,22242,22244,22275,22287,22289,22298,22305,22308,22396,22474,22499,22910,23037,23257,23386';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '18943,19449,20113,20116,21294,21427,21470,21640,21731,22151,22206,22255,22304,22500,23078,23173,23199,23212,23246,51786,51879,51895';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
